<?php
if(!defined('ABSPATH'))exit;
function bsktv_taxonomies(){register_taxonomy('bsktv_city','post',array('labels'=>array('name'=>'城市','singular_name'=>'城市'),'public'=>true,'hierarchical'=>true,'show_admin_column'=>true,'rewrite'=>array('slug'=>'city')));register_taxonomy('bsktv_type','post',array('labels'=>array('name'=>'酒店類型','singular_name'=>'酒店類型'),'public'=>true,'hierarchical'=>true,'show_admin_column'=>true,'rewrite'=>array('slug'=>'ktv-type')));register_taxonomy('bsktv_feature','post',array('labels'=>array('name'=>'店家特色','singular_name'=>'店家特色'),'public'=>true,'hierarchical'=>false,'show_admin_column'=>true,'rewrite'=>array('slug'=>'feature')));}add_action('init','bsktv_taxonomies');
function bsktv_flush_rewrite(){bsktv_taxonomies();flush_rewrite_rules();}add_action('after_switch_theme','bsktv_flush_rewrite');
